diff --git a/mail/components/extensions/parent/ext-mail.js b/mail/components/extensions/parent/ext-mail.js
index e6c95230df2..68062bc25c6 100644
--- a/mail/components/extensions/parent/ext-mail.js
+++ b/mail/components/extensions/parent/ext-mail.js
@@ -1125,6 +1125,11 @@ class Tab extends TabBase {
     // Thunderbird doesn't support tab groups.
     return -1;
   }
+
+  get splitViewId() {
+    // Thunderbird doesn't support split views.
+    return -1;
+  }
 }

